/*
 * @jhai/theme-base — the JHAI token chain, in one file.
 *
 * WHAT THIS IS
 *   Three layers, wired in one direction. A client project overwrites the FIRST layer only
 *   and every component in the @jhai registry, plus every third-party shadcn item, restyles
 *   with it.
 *
 *       --jh-*            the brand layer.  THIS IS THE ONLY BLOCK A CLIENT EDITS.
 *          ↓
 *       shadcn semantics  --background / --foreground / --primary / --border / …
 *          ↓
 *       v2 vocabulary     --ink-* / --paper-* / --bjarmi-* / --type-* / --line-*
 *          ↓
 *       @theme inline     Tailwind utilities: bg-paper-0, text-bjarmi-ink, text-type-section
 *
 * HOW TO USE IT
 *   1. Install:  pnpm dlx shadcn@4.21.0 add @jhai/theme-base
 *   2. Add ONE line at the top of your globals.css, after the tailwind import:
 *
 *        @import "tailwindcss";
 *        @import "./jhai-theme-base.css";
 *
 *   3. To rebrand, append a :root block AFTER that import overriding only --jh-* values.
 *      Nothing else moves. See the CLIENT REBRAND block at the foot of this file.
 *
 * THE NAME CONTRACT (binding — quoted from jhai-new-website/src/styles/v2-theme.css)
 *   "Every custom property below carries the export's own name, verbatim. `--ink-800` is
 *    `--ink-800`. […] a rename is not a refactor, it is 200 silent rendering failures.
 *    Values may move here. Names may not."
 *
 *   This file is that permitted value move and nothing more. Not one v2 token was renamed.
 *   Every v2 colour token now resolves through --jh-*; the type, space and motion tokens
 *   keep their literals because they are not brand-variable.
 *
 * FONTS ARE NOT INCLUDED
 *   --font-sans and --font-mono are declared with system fallbacks only. Schibsted Grotesk
 *   and IBM Plex Mono are self-hosted per project; this file must not assume a /v2/fonts
 *   path exists in a consuming repo.
 */

:root {
  /* ═══════════════════════════════════════════════════════════════════════════
     LAYER 1 — THE BRAND LAYER. Override these, and only these, per client.
     ═══════════════════════════════════════════════════════════════════════════ */

  /* light ground */
  --jh-light-bg: #f5f5f5;
  --jh-light-bg-alt: #ffffff;
  --jh-light-surface-strong: #ececea;
  --jh-light-text: #222222;
  --jh-light-text-muted: #4a4a48;
  --jh-light-text-faint: #6b6b68;
  --jh-light-ink-faint: #8a8a86;
  --jh-light-border: rgba(0, 0, 0, 0.08);
  --jh-light-border-mid: rgba(0, 0, 0, 0.14);

  --jh-bg: var(--jh-light-bg);
  --jh-bg-alt: var(--jh-light-bg-alt);
  --jh-surface: var(--jh-light-bg-alt);
  --jh-surface-strong: var(--jh-light-surface-strong);
  --jh-border: var(--jh-light-border);
  --jh-border-mid: var(--jh-light-border-mid);
  --jh-border-strong: var(--jh-light-ink-faint);
  --jh-text: var(--jh-light-text);
  --jh-text-muted: var(--jh-light-text-muted);
  --jh-text-faint: var(--jh-light-text-faint);
  --jh-ink-faint: var(--jh-light-ink-faint);
  --jh-accent: var(--jh-light-text);
  --jh-accent-contrast: var(--jh-light-bg-alt);

  /* dark ground */
  --jh-invert-bg: #0a0b0b;
  --jh-invert-surface: #151717;
  --jh-invert-surface-strong: #1e2020;
  --jh-invert-l3: #2a2c2c;
  --jh-invert-text: #e8e8e8;
  --jh-invert-text-muted: #b8b8b6;
  --jh-invert-muted: #a0a0a0;
  --jh-invert-ink-faint: #6e6e6b;
  --jh-invert-border: rgba(255, 255, 255, 0.12);
  --jh-invert-border-mid: rgba(255, 255, 255, 0.2);

  /* the one accent */
  --jh-primary: #87a6a6;
  --jh-primary-hover: #9ab8b8;
  --jh-primary-deep: #547070;
  --jh-primary-mid: #729090;
  --jh-primary-lift: #a9c6c6;
  --jh-primary-glow: rgba(135, 166, 166, 0.15);
  --jh-focus-accent: var(--jh-primary-deep);

  /*
   * Added by theme-base because the brand layer had no equivalent and the v2 layer needed
   * one. Extending --jh-* is the correct move; hardcoding in a component is not.
   *
   * --jh-ink-eyebrow  the eyebrow grey. NOT --jh-ink-faint: that is #8a8a86, which measures
   *                   3.47:1 on white, and the eyebrow recipe sets 9.5px type, so WCAG 2.2 AA
   *                   asks 4.5:1. #6e6e6b measures 5.12:1 on white and 4.69:1 on paper.
   *                   The two must stay separate — the border keeps the lighter value because
   *                   a non-text control edge only needs 3:1.
   * --jh-hairline*    kept as their own tokens rather than folded into --jh-border, whose
   *                   alpha is 0.08/0.14 against the hairlines' 0.12/0.06. Folding them would
   *                   have been a silent visual change, which is not a permitted value move.
   */
  --jh-ink-eyebrow: #6e6e6b;
  --jh-ink-disabled: #b0b0ad;
  --jh-hairline: rgba(0, 0, 0, 0.12);
  /* the three control edges the components used to bake in as black/20, white/35, black/8 */
  --jh-edge-light: rgba(0, 0, 0, 0.2);
  --jh-edge-dark: rgba(255, 255, 255, 0.35);
  --jh-rule-light: rgba(0, 0, 0, 0.08);
  --jh-hairline-soft: rgba(0, 0, 0, 0.06);
  --jh-hairline-dark: rgba(255, 255, 255, 0.12);
  --jh-hairline-dark-soft: rgba(255, 255, 255, 0.08);

  --jh-status-alert: #c0524a;
  --jh-radius: 12px;

  /* ═══════════════════════════════════════════════════════════════════════════
     LAYER 2 — shadcn semantics: NOT HERE, deliberately.

     --background / --foreground / --primary / --border and the rest are shipped as the
     `cssVars` block on the @jhai/theme-base registry item, not in this file. The CLI merges
     cssVars INTO the consuming project's own :root, which is declared LATER in globals.css
     than this @import and would otherwise win. Putting them here renders correctly on a
     bare project and silently loses on a real shadcn project — the worst kind of wrong.
     ═══════════════════════════════════════════════════════════════════════════ */

  /* ═══════════════════════════════════════════════════════════════════════════
     LAYER 3 — the v2 vocabulary. NAMES ARE FROZEN. Values resolve through --jh-*.
     ═══════════════════════════════════════════════════════════════════════════ */

  --ink-950: var(--jh-invert-bg);
  --ink-900: var(--jh-invert-surface);
  --ink-800: var(--jh-text);
  --ink-600: var(--jh-text-muted);
  --ink-500: var(--jh-text-faint);
  --ink-400: var(--jh-ink-eyebrow);
  --ink-300: var(--jh-ink-disabled);
  --paper-0: var(--jh-bg-alt);
  --paper-50: var(--jh-bg);

  --dark-text-1: var(--jh-invert-text);
  --dark-text-2: var(--jh-invert-text-muted);
  --dark-text-3: var(--jh-invert-muted);

  /* Bjarmi — the one accent, two sides only. Ink on light grounds, glow on dark.
     It is never a surface colour, and it is never called "sage". */
  --bjarmi-ink: var(--jh-primary-deep);
  --bjarmi-glow: var(--jh-primary);
  --bjarmi-tint: color-mix(in srgb, var(--jh-primary-deep) 6%, transparent);

  --edge-light: var(--jh-edge-light);
  --edge-dark: var(--jh-edge-dark);
  --rule-light: var(--jh-rule-light);
  --line-light: var(--jh-hairline);
  --line-light-soft: var(--jh-hairline-soft);
  --line-dark: var(--jh-hairline-dark);
  --line-dark-soft: var(--jh-hairline-dark-soft);

  --text-heading: var(--ink-800);
  --text-body: var(--ink-600);
  --text-secondary: var(--ink-500);
  --text-eyebrow: var(--ink-400);
  --surface-page: var(--paper-50);
  --surface-raised: var(--paper-0);
  --surface-dark: var(--ink-950);
  --accent-on-dark: var(--bjarmi-glow);

  --shadow-field: 0 10px 40px rgba(10, 11, 11, 0.35);
  --shadow-lift: 0 24px 48px rgba(10, 11, 11, 0.22);

  /* type — not brand-variable, so these keep their literals */
  --font-sans: ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --weight-heading: 500;

  --type-hero: clamp(56px, 6.8vw, 96px);
  --type-display: clamp(56px, 6.6vw, 96px);
  --type-feature: clamp(44px, 4.4vw, 60px);
  --type-section: clamp(40px, 4vw, 52px);
  --type-card-title: 19px;
  --type-card-title-lg: 21px;
  --type-lede: 17px;
  --type-body: 14.5px;
  --type-small: 13.5px;
  --type-caption: 13px;
  --type-eyebrow: 9.5px;
  --type-micro: 10px;

  --measure-lede: 520px;
  --measure-side: 340px;
  --measure-heading: 620px;
  --measure-head-lede: 460px;
  --measure-row: 640px;
  --measure-standfirst: 820px;
  --measure-statement: 900px;
  --measure-term: 220px;

  --eyebrow-gap: 20px;
  --container: 1280px;
  --gutter: 48px;
  --section-y: 150px;
  --section-y-display: 160px;
  --header-offset: 120px;
  --gap-heading-block: 56px;
  --gap-grid: 48px;
  --gap-card: 20px;
  --gap-inline: 12px;

  --radius-card: 12px;
  --radius-inner: 8px;
  --radius-pill: 999px;
  --button-h: 50px;
  --button-h-nav: 42px;
  --field-h: 56px;

  --ease: cubic-bezier(0.2, 0, 0, 1);
  --dur-fast: 200ms;
  --dur-med: 400ms;
  --dur-slow: 700ms;
  --hover-img-scale: 1.02;
  --hover-arrow-shift: 4px;
}

/*
 * The v2 semantic aliases under .dark.
 *
 * WHAT THIS FIXES, AND WHAT IT DOES NOT — measured 2026-09-12.
 *
 * The v2 system was authored around a `ground` prop, not a `.dark` class: a component is told
 * which surface it sits on and picks its own side. That still works and is still the designed
 * mechanism. But a project that toggles `.dark` at the root — which every shadcn project
 * expects to work — used to get inverted shadcn tokens and a completely unmoved v2 layer, so
 * every JHAI component rendered light-mode ink on a dark ground. Unreadable, and silent.
 *
 * This block repoints the SEMANTIC aliases so text and surfaces invert. It deliberately does
 * NOT invert the RAMP names. `--ink-500` means "step 500 of the ink ramp", not "secondary
 * text"; flipping it would make the name lie, and the ramp is what the `ground="dark"` path
 * reads to paint its own dark side. Inverting both would double-invert every dark band.
 *
 * CONSEQUENCE, know this before relying on it: a component that reaches for a ramp utility
 * directly (`text-ink-500`, `text-ink-400`, `text-ink-300`) still renders its light value
 * under `.dark`. Four items do: StatTile's caption, CheckList's cross mark, ImageSlot's
 * placeholder, ComparisonTable's muted cells. For those, pass `ground="dark"` — which is what
 * the prop is for — or set the ramp yourself in your own `.dark` block.
 */
.dark {
  --text-heading: var(--jh-invert-text);
  --text-body: var(--jh-invert-text-muted);
  --text-secondary: var(--jh-invert-muted);
  --text-eyebrow: var(--jh-invert-muted);
  --surface-page: var(--jh-invert-bg);
  --surface-raised: var(--jh-invert-surface);
  --accent: var(--bjarmi-glow);
  --line-light: var(--jh-hairline-dark);
  --line-light-soft: var(--jh-hairline-dark-soft);
}

.dark {
  --background: var(--jh-invert-bg);
  --foreground: var(--jh-invert-text);
  --card: var(--jh-invert-surface);
  --card-foreground: var(--jh-invert-text);
  --popover: var(--jh-invert-surface);
  --popover-foreground: var(--jh-invert-text);
  --primary: var(--jh-invert-text);
  --primary-foreground: var(--jh-invert-bg);
  --secondary: var(--jh-invert-surface-strong);
  --secondary-foreground: var(--jh-invert-text);
  --muted: var(--jh-invert-surface-strong);
  --muted-foreground: var(--jh-invert-text-muted);
  --accent: var(--jh-invert-l3);
  --accent-foreground: var(--jh-invert-text);
  --destructive: var(--jh-status-alert);
  --border: var(--jh-invert-border);
  --input: var(--jh-invert-border-mid);
  --ring: var(--jh-primary);
  --chart-1: var(--jh-invert-text);
  --chart-2: var(--jh-invert-text-muted);
  --chart-3: var(--jh-invert-muted);
  --chart-4: var(--jh-invert-ink-faint);
  --chart-5: var(--jh-primary);
  --sidebar: var(--jh-invert-surface);
  --sidebar-foreground: var(--jh-invert-text);
  --sidebar-primary: var(--jh-primary);
  --sidebar-primary-foreground: var(--jh-invert-bg);
  --sidebar-accent: var(--jh-invert-l3);
  --sidebar-accent-foreground: var(--jh-invert-text);
  --sidebar-border: var(--jh-invert-border);
  --sidebar-ring: var(--jh-primary);
}

/*
 * LAYER 4 — the Tailwind projection. Aliases point AT the v2 names, one direction only,
 * so `text-bjarmi-ink` and `text-type-section` resolve. Never a second vocabulary.
 */
@theme inline {
  --color-ink-950: var(--ink-950);
  --color-ink-900: var(--ink-900);
  --color-ink-800: var(--ink-800);
  --color-ink-600: var(--ink-600);
  --color-ink-500: var(--ink-500);
  --color-ink-400: var(--ink-400);
  --color-ink-300: var(--ink-300);
  --color-paper-0: var(--paper-0);
  --color-paper-50: var(--paper-50);
  --color-dark-text-1: var(--dark-text-1);
  --color-dark-text-2: var(--dark-text-2);
  --color-dark-text-3: var(--dark-text-3);
  --color-bjarmi-ink: var(--bjarmi-ink);
  --color-bjarmi-glow: var(--bjarmi-glow);
  --color-bjarmi-tint: var(--bjarmi-tint);
  --color-edge-light: var(--edge-light);
  --color-edge-dark: var(--edge-dark);
  --color-rule-light: var(--rule-light);
  --color-line-light: var(--line-light);
  --color-line-light-soft: var(--line-light-soft);
  --color-line-dark: var(--line-dark);
  --color-line-dark-soft: var(--line-dark-soft);
  --color-text-heading: var(--text-heading);
  --color-text-body: var(--text-body);
  --color-text-secondary: var(--text-secondary);
  --color-text-eyebrow: var(--text-eyebrow);
  --color-surface-page: var(--surface-page);
  --color-surface-raised: var(--surface-raised);
  --color-surface-dark: var(--surface-dark);

  --text-type-hero: var(--type-hero);
  --text-type-display: var(--type-display);
  --text-type-feature: var(--type-feature);
  --text-type-section: var(--type-section);
  --text-type-card-title: var(--type-card-title);
  --text-type-card-title-lg: var(--type-card-title-lg);
  --text-type-lede: var(--type-lede);
  --text-type-body: var(--type-body);
  --text-type-small: var(--type-small);
  --text-type-caption: var(--type-caption);
  --text-type-eyebrow: var(--type-eyebrow);
  --text-type-micro: var(--type-micro);

  /* NOTE: no --font-heading family token, anywhere. Tailwind v4 resolves `font-heading`
     against the FAMILY namespace first, so declaring one makes `font-heading` set a
     font-family and silently drop the 500 weight. Components write
     [font-weight:var(--weight-heading)] instead, which is unambiguous. */
  --font-weight-heading: var(--weight-heading);

  --spacing-gutter: var(--gutter);
  --spacing-section-y: var(--section-y);
  --spacing-section-y-display: var(--section-y-display);
  --spacing-header-offset: var(--header-offset);
  --spacing-gap-heading-block: var(--gap-heading-block);
  --spacing-gap-grid: var(--gap-grid);
  --spacing-gap-card: var(--gap-card);
  --spacing-gap-inline: var(--gap-inline);
  --spacing-eyebrow-gap: var(--eyebrow-gap);
  --spacing-button-h: var(--button-h);
  --spacing-button-h-nav: var(--button-h-nav);
  --spacing-field-h: var(--field-h);

  --container-container: var(--container);
  --container-measure-lede: var(--measure-lede);
  --container-measure-side: var(--measure-side);
  --container-measure-heading: var(--measure-heading);
  --container-measure-head-lede: var(--measure-head-lede);
  --container-measure-row: var(--measure-row);
  --container-measure-standfirst: var(--measure-standfirst);
  --container-measure-statement: var(--measure-statement);
  --container-measure-term: var(--measure-term);

  --radius-card: var(--radius-card);
  --radius-inner: var(--radius-inner);
  --radius-pill: var(--radius-pill);
}

/* The one invariant that is not a token. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/*
 * ═════════════════════════════════════════════════════════════════════════════
 * CLIENT REBRAND — copy this into the consuming project's globals.css, AFTER the
 * import above, and change the values. Nine tokens carry a whole brand.
 * ═════════════════════════════════════════════════════════════════════════════
 *
 * :root {
 *   --jh-light-bg:        #fdfbf7;
 *   --jh-light-bg-alt:    #ffffff;
 *   --jh-light-text:      #1a1614;
 *   --jh-light-text-muted:#4d443f;
 *   --jh-light-text-faint:#6f635c;
 *   --jh-invert-bg:       #14100e;
 *   --jh-invert-text:     #f2ece4;
 *   --jh-primary:         #c2703d;
 *   --jh-primary-deep:    #8a4a22;
 * }
 */

docs:
Add ONE line to your globals.css, immediately after the tailwind import:

    @import "tailwindcss";
    @import "../styles/jhai-theme-base.css";

Adjust the relative path to wherever the file landed. To rebrand, append a :root block AFTER that import overriding only --jh-* values — see the CLIENT REBRAND block at the foot of the file.

The shadcn semantic tokens (--background, --foreground, --primary, --border and the rest) are NOT in that CSS file. They arrive as cssVars, which the CLI merges into your project's own :root block. That is deliberate: your :root is declared later in globals.css than the @import, so a mapping inside the file would render correctly on a bare project and silently lose on a real shadcn one.

Do not edit any --ink-*, --paper-*, --bjarmi-* or shadcn semantic token directly. They resolve through --jh-* and editing them breaks the chain.

WHY type IS registry:theme AND NOT registry:base — measured, shadcn CLI 4.21.0. A registry:base item's cssVars block is silently ignored: the files land, the CLI reports success, and not one token reaches globals.css. registry:theme applies them correctly. There is no error and no warning, so this is only visible by diffing globals.css after an install.
